function beginGame(){resetRun();game.mode='playing';setScreen(null);$('#intro-screen').classList.remove('visible');$('#game-ui').classList.add('active');renderer.domElement.requestPointerLock?.();showToast(tr('EINSATZ 04—17 · FUNKVERBINDUNG INSTABIL','OPERATION 04—17 · RADIO LINK UNSTABLE'),3200);lastTime=performance.now();}
function beginIntro(){game.mode='intro';setScreen('intro-screen');$('#intro-title').innerHTML='SOMEWHERE BELOW YOU,<br>IT IS ALREADY AWAKE.';$('#intro-text').innerHTML='The recorder clicks. A voice—hoarse, terrified—fills the dark.<br>“If the lights are dead, don\'t make a sound. It follows the noise.”';$('#intro-subtitle').textContent='';$('#intro-screen').querySelector('.intro-progress span').style.width='0';let progress=0;clearInterval(beginIntro.timer);beginIntro.timer=setInterval(()=>{progress+=2.5;$('#intro-screen').querySelector('.intro-progress span').style.width=Math.min(100,progress)+'%';if(progress>=100){clearInterval(beginIntro.timer);beginGame();}},240);}

function nearInteraction(){let best=null,bestD=Infinity;for(const it of interactables){if(it.used)continue;const d=player.pos.distanceTo(it.pos);if(d<it.r&&d<bestD){best=it;bestD=d;}}return best;}
function toggleFlashlight(){if(!game.hasFlashlight||game.battery<=0){showToast(tr('Taschenlampe ohne Ladung.','Flashlight battery depleted.'));return;}flashOn=!flashOn;flashlight.intensity=flashOn?3.1:0;flashlight.userData.fill.intensity=flashOn?.32:0;$('#equipment').innerHTML=tr(`${flashOn?'▰':'▱'} Taschenlampe <span>◉ Walkie-talkie</span>`,`${flashOn?'▰':'▱'} Flashlight <span>◉ Walkie-talkie</span>`);playTone(flashOn?420:190,.06,'square',.025);}
function moveAxis(axis,amount){if(!amount)return;const steps=Math.max(1,Math.ceil(Math.abs(amount)/.1)),step=amount/steps,radius=.32;for(let i=0;i<steps;i++){const next=player.pos.clone();next[axis]+=step;let blocked=false;for(const c of colliders){if(c.disabled)continue;const hx=c.w/2+radius,hz=c.d/2+radius;if(Math.abs(next.x-c.x)<hx&&Math.abs(next.z-c.z)<hz&&player.pos.y<c.h+.25){blocked=true;break;}}if(blocked)break;player.pos[axis]=next[axis];}}
function damage(amount){if(game.damageCooldown>0||game.playerDown||game.mode!=='playing')return;game.health=Math.max(0,game.health-amount);game.damageCooldown=1.15;$('#damage-vignette').style.opacity='.78';setTimeout(()=>$('#damage-vignette').style.opacity='0',240);playTone(58,.22,'sawtooth',.1);if(game.health<=0){game.playerDown=true;$('#down-overlay').classList.add('show');game.revive=0;}}
function setPaused(value){if(game.mode!=='playing')return;game.paused=value;$('#pause-screen').classList.toggle('show',value);if(value)document.exitPointerLock?.();else renderer.domElement.requestPointerLock?.();}
function updateMonster(dt){if(!monster?.userData.active)return;monster.visible=true;const to=player.pos.clone().sub(monster.position);to.y=0;const dist=to.length();game.enemyDist=dist;game.enemyAlert=Math.max(game.enemyAlert,clamp(1-dist/22,0,1));const dir=to.normalize();const speed=game.called?1.48+Math.max(0,1-game.hold/60)*.28:1.05;monster.position.addScaledVector(dir,speed*dt);monster.rotation.y=Math.atan2(dir.x,dir.z);monster.position.y=.025+Math.sin(game.elapsed*5)*.035;if(dist<1.38)damage(game.called?22:14);monsterLight.intensity=1.1+Math.sin(game.elapsed*9)*.35;}
function updateBots(dt){for(let i=0;i<bots.length;i++){const bot=bots[i],off=bot.userData.offset;const target=new THREE.Vector3(player.pos.x+off.x,0,player.pos.z+off.z);const delta=target.sub(bot.position);delta.y=0;const d=delta.length();if(d>1.3){delta.normalize();bot.position.addScaledVector(delta,Math.min(d-1.1,2.25*dt));bot.rotation.y=Math.atan2(delta.x,delta.z);}}}
function updateHud(dt){const battery=$('#battery-meter');if(battery){battery.querySelector('b').textContent=`${Math.ceil(game.battery)}%`;battery.querySelector('i').style.width=`${game.battery}%`;battery.classList.toggle('low',game.battery<20);}$('#fear-vignette').style.opacity=String(clamp(game.fear/150,0,.72));if(game.called&&game.hold>0){$('#objective-text').textContent=`${objectives[game.lang][5]}  ·  ${Math.ceil(game.hold)}s`;}if(game.playerDown){game.revive+=dt*(bots.length?1/7:0);$('#down-overlay .revive-meter i').style.width=`${clamp(game.revive*100,0,100)}%`;if(game.revive>=1){game.playerDown=false;game.health=35;$('#down-overlay').classList.remove('show');showToast(tr('Dein Team hat dich stabilisiert.','Your team stabilized you.'));}}}
