function wireUI(){document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action){handleAction(action);return;}const lang=e.target.closest('[data-lang]')?.dataset.lang;if(lang){game.lang=lang;$$('[data-lang]').forEach(b=>b.classList.toggle('selected',b.dataset.lang===lang));localize();updateObjectives();return;}});$('#skip-intro').addEventListener('click',()=>{clearInterval(beginIntro.timer);beginGame();});$('#subtitle-toggle').addEventListener('click',e=>{game.subtitleOn=!game.subtitleOn;e.currentTarget.classList.toggle('on',game.subtitleOn);e.currentTarget.textContent=game.subtitleOn?'ON':'OFF';});$('#copy-code').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(game.roomCode);showToast(tr('Raumcode kopiert.','Room code copied.'));}catch{showToast(game.roomCode);}});$('#fill-bots').addEventListener('click',()=>{game.botCount=3;$('#bot-row').style.display='flex';$('#lobby-status').textContent=tr('KI-TEAM EINSATZBEREIT · 3 OPERATIVE','BOT SQUAD READY · 3 OPERATIVES');});$('#join-button').addEventListener('click',()=>{const code=$('#join-code').value.trim().toUpperCase();$('#lobby-status').textContent=code?tr('CODE IST LOKAL · ONLINE-SERVER NICHT VERFÜGBAR','CODE IS LOCAL · NO ONLINE SERVER AVAILABLE'):tr('BITTE EINEN 4-STELLIGEN CODE EINGEBEN','ENTER A FOUR-CHARACTER CODE');});$('#sound-toggle').addEventListener('click',()=>{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();playTone(440,.1,'sine',.04);});$('#game').addEventListener('click',()=>{if(game.mode==='playing'&&!game.paused&&!pointer)renderer.domElement.requestPointerLock?.();});document.addEventListener('pointerlockchange',()=>{pointer=document.pointerLockElement===renderer.domElement;});document.addEventListener('mousemove',e=>{if(pointer&&game.mode==='playing'&&!game.paused){const sens=Number($('#sensitivity-slider').value)/80*.0022;player.yaw-=e.movementX*sens;player.pitch=clamp(player.pitch-e.movementY*sens,-1.45,1.45);}});document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keysDown.add(e.code);if(e.repeat)return;if(e.code==='Escape'&&game.mode==='playing'){setPaused(!game.paused);return;}if(game.mode!=='playing')return;if(e.code==='KeyE'&&!game.paused){if(game.playerDown){game.revive=Math.min(1,game.revive+.08);return;}const it=nearInteraction();if(it){const result=it.fn();if((it.kind==='item'||it.kind==='key')&&result!==false)it.used=true;}return;}if(e.code==='KeyF'&&!game.paused)toggleFlashlight();if(e.code==='KeyJ'&&!game.paused)$('#objective-log').classList.toggle('open');if(e.code==='KeyQ'&&!game.paused&&game.hasRadio){playTone(620,.07,'square',.03);showToast(tr('FUNKRAUSCHEN · KEIN SIGNAL','RADIO STATIC · NO SIGNAL'),1200);}});document.addEventListener('keyup',e=>keysDown.delete(e.code));window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);if(composer)composer.setSize(innerWidth,innerHeight);});}

