import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 750 }, deviceScaleFactor: 1 });
page.setDefaultTimeout(15000);
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://127.0.0.1:4173', { waitUntil: 'load' });
await page.waitForTimeout(1500);
const screen = async (path, timeout = 8000) => {
  const session = await page.context().newCDPSession(page);
  try {
    const { data } = await Promise.race([
      session.send('Page.captureScreenshot', { format: 'jpeg', quality: 78, fromSurface: true, captureBeyondViewport: false }),
      new Promise((_, rej) => setTimeout(() => rej(new Error('screenshot timeout')), timeout)),
    ]);
    writeFileSync(path, Buffer.from(data, 'base64'));
    console.log('saved', path);
  } finally { await session.detach().catch(() => {}); }
};
const visible = async id => await page.locator(`#${id}`).evaluate(e => getComputedStyle(e).display !== 'none');
console.log('title:', await page.title(), 'menu:', await visible('main-menu'), 'canvas:', await page.locator('#game').evaluate(c => [c.width, c.height]));
await screen('/tmp/opencode/menu.jpg');
// start offline game
await page.locator('[data-action=lobby]').click();
await page.locator('[data-action=offline]').click();
await page.locator('[data-action=launch]').click();
await page.waitForTimeout(1200);
console.log('game-ui active:', await page.locator('#game-ui').getAttribute('class'));
await screen('/tmp/opencode/game-start.jpg');
console.log('errors:', errors);
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const headed = process.argv.includes('--headed');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const opts = headed ? { ...config.browser.launchOptions, timeout: 30000 } : { headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader'] };
const browser = await chromium.launch(opts);
const page = await browser.newPage({ viewport: { width: 1200, height: 750 }, deviceScaleFactor: 1 });
page.setDefaultTimeout(60000);
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const t0 = Date.now();
await page.goto('http://127.0.0.1:4173', { waitUntil: 'domcontentloaded', timeout: 60000 });
console.log('domcontentloaded', Date.now() - t0);
await page.waitForTimeout(3000);
console.log('ready', Date.now() - t0, 'errors', errors);
console.log('canvas', await page.locator('#game').evaluate(c => [c.width, c.height]));
const session = await page.context().newCDPSession(page);
try {
  const { data } = await Promise.race([
    session.send('Page.captureScreenshot', { format: 'jpeg', quality: 78, fromSurface: true, captureBeyondViewport: false }),
    new Promise((_, rej) => setTimeout(() => rej(new Error('screenshot timeout')), 10000)),
  ]);
  writeFileSync('/tmp/opencode/menu.jpg', Buffer.from(data, 'base64'));
  console.log('saved menu');
} catch (e) { console.log('screenshot failed', e.message); }
await session.detach().catch(() => {});
await browser.close();

