import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 800, height: 600 }, deviceScaleFactor: 1 });
page.setDefaultTimeout(30000);
const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
const t0=Date.now();
await page.goto('http://127.0.0.1:4173/gpu-test.html', { waitUntil: 'load', timeout: 30000 });
console.log('loaded', Date.now()-t0, 'ready', await page.evaluate(() => window.ready), 'errors', errors);
const session = await page.context().newCDPSession(page);
const { data } = await session.send('Page.captureScreenshot', { format: 'jpeg', quality: 80, fromSurface: true });
writeFileSync('/tmp/opencode/gpu-test.jpg', Buffer.from(data, 'base64'));
console.log('saved', Date.now()-t0);
await browser.close();

