input.command:
cd /home/runner/work/the-facility-null.S/the-facility-null.S && cat >> style.css <<'EOF'

/* ── v3: loading, diegetic HUD, co-op, touch ───────────────────────────── */
.creator-sub{font:300 10px var(--mono);letter-spacing:.28em;color:#8b7d63;margin:-12px 0 21px 5px;text-shadow:0 0 10px rgba(205,176,112,.18)}
.loading{position:fixed;inset:0;z-index:30;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 45%,#111612,#040505 70%);transition:opacity .7s}
.loading.hide{opacity:0;pointer-events:none}
.loading-inner{text-align:center;width:min(340px,80vw)}
.loading-inner .brand-mark{font:54px var(--serif);letter-spacing:.1em;color:#d7d2c5}
.loading-label{font:10px var(--mono);letter-spacing:.25em;color:#8d8e81;margin:24px 0 13px}
.loading-bar{height:2px;background:#272b25;overflow:hidden}
.loading-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#6d2a21,#c07b4f);box-shadow:0 0 12px #a14331;transition:width .25s}
.loading-inner small{display:block;margin-top:15px;font:8px var(--mono);letter-spacing:.2em;color:#5c5f56}
.segmented.wide button{width:auto;min-width:82px;padding:0 10px;font-size:9px;letter-spacing:.08em}
.hold-track{position:absolute;left:0;right:0;bottom:-5px;height:2px;background:#34352e;display:none}
.hold-track i{display:block;height:100%;width:0;background:#c28152;box-shadow:0 0 8px #b25e39}
.interaction.holding .hold-track{display:block}
.blood-overlay{position:absolute;inset:0;opacity:0;pointer-events:none;transition:opacity .8s;background:
  radial-gradient(ellipse at 14% 18%,rgba(91,8,7,.5),transparent 24%),
  radial-gradient(ellipse at 83% 29%,rgba(107,9,8,.43),transparent 19%),
  radial-gradient(ellipse at 68% 82%,rgba(79,5,5,.5),transparent 26%),
  radial-gradient(ellipse at 25% 78%,rgba(116,10,8,.4),transparent 21%),
  radial-gradient(ellipse at 50% 50%,transparent 38%,rgba(74,4,4,.5) 100%);
  filter:blur(1.5px)}
.pulse-overlay{position:absolute;inset:0;opacity:0;pointer-events:none;background:radial-gradient(ellipse at 50% 50%,transparent 46%,rgba(118,15,10,.34) 92%);animation:pulsebeat 1.05s infinite}
@keyframes pulsebeat{0%,100%{opacity:.12}18%{opacity:.7}30%{opacity:.22}46%{opacity:.55}}
.voice-indicator{position:absolute;right:39px;top:56px;display:none;align-items:center;gap:7px;font:8px var(--mono);letter-spacing:.14em;color:#8d8d80;background:rgba(5,7,6,.6);border:1px solid rgba(140,140,120,.2);padding:5px 9px}
.voice-indicator.on{display:flex}
.voice-dot{width:5px;height:5px;border-radius:50%;background:#5f665d}
.voice-indicator.talking .voice-dot{background:#c25a42;box-shadow:0 0 9px #b33f2c}
.voice-indicator.talking{color:#e0b795;border-color:rgba(190,112,76,.45)}
.timer-card{position:absolute;left:50%;top:27px;transform:translateX(-50%);display:none;align-items:baseline;gap:9px;background:rgba(7,9,8,.72);border-top:1px solid rgba(190,86,65,.5);padding:7px 14px;font:8px var(--mono);letter-spacing:.18em;color:#9b9282}
.timer-card.show{display:flex}
.timer-card b{font:15px var(--mono);color:#d8b48d;letter-spacing:.1em}
.timer-card.danger{border-color:#c04a35;animation:alarmpulse 1.1s infinite}
.timer-card.danger b{color:#e26f56}
@keyframes alarmpulse{50%{background:rgba(90,16,11,.45)}}
.squad-status{position:absolute;right:39px;top:92px;display:none;flex-direction:column;gap:5px;font:8px var(--mono);letter-spacing:.08em;color:#99998c;text-align:right}
.game-ui.coop .squad-status{display:flex}
.squad-status .sq{display:flex;align-items:center;justify-content:flex-end;gap:7px}
.squad-status .sq i{width:5px;height:5px;border-radius:50%;background:#6d8a6c;box-shadow:0 0 6px #5b7d5b}
.squad-status .sq.down i{background:#b24d38;box-shadow:0 0 7px #a33b29}
.squad-status .sq b{color:#cbc6b6;font-weight:400}
.squad-status .sq em{font-style:normal;color:#7a7c72}
.pause-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px 26px;margin:0 0 27px;width:min(390px,82vw);text-align:left}
.pause-controls div{display:flex;align-items:center;gap:11px;border-bottom:1px solid rgba(160,155,135,.12);padding:6px 0}
.pause-controls b{min-width:38px;font:9px var(--mono);color:#d1ac7d;letter-spacing:.1em}
.pause-controls span{font:10px var(--mono);color:#85867b;letter-spacing:.08em}
.ending-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;margin-top:26px}
.ending-actions .menu-btn{margin-top:0}
.game-ui.immersive .status-left,.game-ui.immersive .status-right,.game-ui.immersive .crosshair,.game-ui.immersive .voice-indicator{display:none!important}
.game-ui.immersive .objective-card{transition:opacity 1.4s;opacity:.92}
.game-ui.immersive .objective-card.fade{opacity:0}
.game-ui.immersive .objective-hint{opacity:.45}
.game-ui.immersive .objective-log{background:rgba(8,11,9,.97)}
.toast.warn{border-left-color:#c04a35;color:#f0d3c5}
.toast.good{border-left-color:#7d9b6d;color:#dfe9d2}
.subtitles-line.show{opacity:1}
.subtitles-line{opacity:0;transition:opacity .25s;background:rgba(3,5,4,.38);padding:4px 12px}
.touch-controls{position:fixed;inset:0;z-index:8;display:none;pointer-events:none}
.touch-controls.on{display:block}
.touch-stick{position:absolute;left:22px;bottom:26px;width:112px;height:112px;border-radius:50%;border:1px solid rgba(190,186,164,.28);background:rgba(6,8,7,.34);pointer-events:auto}
