}
function addBotsToRoom() {
  const names = BOT_NAMES.filter(n => !game.roomPlayers.some(p => p.name === n));
  while (game.roomPlayers.length < 4 && names.length) {
    const n = names.shift();
    game.roomPlayers.push({ name: n, role: 'AI OPERATIVE', bot: true });
