import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 750 }, deviceScaleFactor: 1 });
page.setDefaultTimeout(25000);
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://127.0.0.1:4173/?quality=low', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1200);
// start solo directly
await page.evaluate(() => { window.__facility.game.solo = true; window.__facility.beginGame(); });
await page.evaluate(() => document.exitPointerLock?.());
await page.waitForTimeout(2500);
console.log('state', await page.evaluate(() => { const f = window.__facility; return { mode: f.game.mode, solo: f.game.solo, bots: f.bots.length, health: f.game.health, ui: document.querySelector('#game-ui').className }; }));
// try playwright screenshot
try {
  await page.screenshot({ path: '/tmp/opencode/v4-game.jpg', type: 'jpeg', quality: 78, animations: 'disabled', timeout: 20000 });
  console.log('pw shot ok');
} catch (e) { console.log('pw shot failed', e.message); }

// Campaign flow programmatically
const flow = await page.evaluate(async () => {
  const f = window.__facility, g = f.game;
  const log = [];
  // read journal
  g.journalRead = true; g.storyDone = true; g.phase = 1;
  // open security door
  const sec = f.doors.find(d => d.id === 'security');
  f.toggleFlashlight();
  // take gear via interactables? just set flags
  g.hasFlashlight = true; g.hasRadio = true; g.flashlightOn = true;
  // collect keys in order
  f.collectKey(0, { visible: true });
  f.collectKey(1, { visible: true });
  f.collectKey(2, { visible: true });
  log.push('keys=' + JSON.stringify(g.keys));
  // open med and lab doors
  f.tryDoor('med'); f.tryDoor('lab');
  const med = f.doors.find(d => d.id === 'med'), lab = f.doors.find(d => d.id === 'lab');
  log.push('doors med/lab target=' + med.target + '/' + lab.target);
  // restore power
  f.restorePower();
  log.push('power=' + g.power + ' detonation=' + g.detonation);
  // call lift
  f.useLiftPanel();
  log.push('elevatorCalled=' + g.elevatorCalled + ' hold=' + g.hold);
  // fast forward hold by setting hold small and ticking? just set escapeReady
  g.hold = 0.1;
  return log;
});
console.log('flow', flow);
await page.waitForTimeout(400);
const afterHold = await page.evaluate(() => { const g = window.__facility.game; return { escapeReady: g.escapeReady, hold: g.hold }; });
console.log('afterHold', afterHold);
// board elevator -> win
await page.evaluate(() => window.__facility.boardElevator());
await page.waitForTimeout(500);
const ending = await page.evaluate(() => { const g = window.__facility.game; return { mode: g.mode, ending: g.ending, won: g.endingWon, title: document.querySelector('#ending-title').textContent, screen: document.querySelector('#ending-screen').className }; });
console.log('ending', ending);
console.log('errors', errors);
await browser.close();

