import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 750 }, deviceScaleFactor: 1 });
page.setDefaultTimeout(25000);
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const shot = async (name) => {
  try { await page.screenshot({ path: `/tmp/opencode/${name}.jpg`, type: 'jpeg', quality: 80, animations: 'disabled', timeout: 20000 }); console.log('shot', name); }
  catch (e) { console.log('shot failed', name, e.message); }
};
await page.goto('http://127.0.0.1:4173/?quality=low', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1000);
await page.evaluate(() => { const f = window.__facility; f.game.solo = true; f.beginGame(); });
await page.evaluate(() => document.exitPointerLock?.());
await page.waitForTimeout(2200);
await shot('v5-spawn');
console.log('spawn', await page.evaluate(() => { const g = window.__facility.game; return { mode: g.mode, flash: g.hasFlashlight, on: g.flashlightOn, bat: g.battery, yaw: window.__facility.player.yaw }; }));
// Move to medical ward and look around
await page.evaluate(() => { const f = window.__facility; f.tp(0, -14, Math.PI); f.game.journalRead = true; f.game.storyDone = true; });
await page.waitForTimeout(700);
await shot('v5-medical');
// Reactor with power on
await page.evaluate(() => { const f = window.__facility; f.forcePower(); f.tp(0, -56, Math.PI); });
await page.waitForTimeout(700);
await shot('v5-reactor');
console.log('errors', errors);
await browser.close();

