import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 750 }, deviceScaleFactor: 1 });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const shot = async (name) => {
  try { await page.screenshot({ path: `/tmp/opencode/${name}.jpg`, type: 'jpeg', quality: 80, animations: 'disabled', timeout: 45000 }); console.log('shot', name); }
  catch (e) { console.log('shot failed', name, e.message); }
};
await page.goto('http://127.0.0.1:4173/?quality=low', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1200);
await shot('ui-menu');
await page.locator('[data-action=settings]').click();
await page.waitForTimeout(300);
await shot('ui-settings');
await page.locator('#settings-screen [data-action=back]').click();
await page.locator('[data-action=credits]').click();
await page.waitForTimeout(300);
await shot('ui-archive');
await page.locator('#archive-screen [data-action=back]').click();
await page.locator('[data-action=lobby]').click();
await page.waitForTimeout(300);
await shot('ui-lobby');
await page.locator('[data-action=host]').click();
await page.waitForTimeout(300);
await shot('ui-room');
await page.locator('[data-action=backLobby]').click();
await page.locator('[data-action=back]').click();
// intro
await page.evaluate(() => window.__facility.beginIntro());
await page.waitForTimeout(2600);
await shot('ui-intro');
await page.evaluate(() => window.__facility.beginGame(true));
await page.evaluate(() => document.exitPointerLock?.());
await page.waitForTimeout(1200);
// pause
await page.evaluate(() => window.__facility.setPaused(true));
await page.waitForTimeout(300);
await shot('ui-pause');
await page.evaluate(() => window.__facility.setPaused(false));
// ending
await page.evaluate(() => { const f = window.__facility; f.game.mode = 'playing'; f.forceLift(); });
await page.waitForTimeout(300);
await page.evaluate(() => window.__facility.boardElevator());
await page.waitForTimeout(500);
await shot('ui-ending');
console.log('errors', errors);
await browser.close();

import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1000, height: 700 } });
page.setDefaultTimeout(20000);
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const tp = (x, z, yaw = 0) => page.evaluate(([x, z, yaw]) => window.__facility.tp(x, z, yaw), [x, z, yaw]);
const pressE = async () => { await page.keyboard.down('KeyE'); await page.waitForTimeout(90); await page.keyboard.up('KeyE'); await page.waitForTimeout(120); };
const holdE = async (ms) => { await page.keyboard.down('KeyE'); await page.waitForTimeout(ms); await page.keyboard.up('KeyE'); await page.waitForTimeout(150); };
const state = () => page.evaluate(() => { const f = window.__facility, g = f.game; return { story: g.storyDone, journal: g.journalRead, keys: g.keys.slice(), power: g.power, breakers: g.breakers.slice(), elevator: g.elevatorCalled, escape: g.escapeReady, mode: g.mode, won: g.endingWon, health: g.health, doors: f.doors.map(d => d.id + ':' + d.target) }; });

await page.goto('http://127.0.0.1:4173/?quality=low', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(900);
await page.evaluate(() => { window.__facility.game.solo = true; window.__facility.beginGame(); });
await page.evaluate(() => document.exitPointerLock?.());
await page.waitForTimeout(600);

// read journal
await tp(0, 3.55, Math.PI); await pressE();
console.log('after journal', await state());

// unlock security door
await tp(2.7, -5.7, Math.PI); await pressE();
console.log('after security', await state());

// MED key
await tp(0, -18.0, Math.PI); await pressE();
console.log('after MED key', await state());

// MED door
await tp(0, -25.7, Math.PI); await pressE();
console.log('after MED door', await state());

// LAB key
await tp(4.3, -41.0, Math.PI); await pressE();
console.log('after LAB key', await state());

// LAB door
await tp(0, -46.7, Math.PI); await pressE();
console.log('after LAB door', await state());

// REACTOR key
await tp(-4.3, -56.0, Math.PI); await pressE();
console.log('after REACTOR key', await state());

// Breaker A (hold)
await tp(-4.3, -66.0, Math.PI); await holdE(1400);
console.log('after breaker A', await state());

// Breaker B (hold)
await tp(4.3, -66.0, Math.PI); await holdE(1400);
console.log('after breaker B', await state());

// Call lift
await tp(3.55, -81.3, Math.PI); await pressE();
console.log('after call', await state());

// speed up hold
await page.evaluate(() => { window.__facility.game.hold = 0.05; });
await page.waitForTimeout(500);
console.log('after hold', await state());

// Board
await tp(0, -86.0, Math.PI); await pressE();
await page.waitForTimeout(400);
console.log('after board', await state());
console.log('ending dom', await page.evaluate(() => ({ title: document.querySelector('#ending-title').textContent, screen: document.querySelector('#ending-screen').className })));

// Pause check in fresh run
await page.evaluate(() => { const f = window.__facility; f.quitToMenu(); f.game.solo = true; f.beginGame(); });
await page.evaluate(() => document.exitPointerLock?.());
await page.waitForTimeout(400);
await page.evaluate(() => window.__facility.setPaused(true));
console.log('pause', await page.evaluate(() => ({ paused: window.__facility.game.paused, cls: document.querySelector('#pause-screen').className })));
await page.evaluate(() => window.__facility.setPaused(false));
console.log('resume', await page.evaluate(() => window.__facility.game.paused));

// Monster damage test
await page.evaluate(() => { const f = window.__facility; f.game.health = 100; f.activateMonster ? f.activateMonster(true) : null; });
const dmg = await page.evaluate(async () => {
  const f = window.__facility, g = f.game;
  if (f.monster) { f.monster.visible = true; f.monster.userData.active = true; f.monster.position.set(f.player.pos.x, 0, f.player.pos.z + 1.0); }
  const before = g.health;
  await new Promise(r => setTimeout(r, 1800));
  return { before, after: g.health };
});
console.log('monster damage', dmg);
console.log('errors', errors);
await browser.close();
